import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmListCurso = () => {
  const [cursos, setCursos] = useState([]); // Estado para armazenar os cursos
  const [novoCurso, setNovoCurso] = useState(""); // Nome do novo curso a ser adicionado
  const [cursoEditando, setCursoEditando] = useState(null); // Curso que está sendo editado
  const [formData, setFormData] = useState({
    nome: "",
    nivel: 1,
    periodo: "Manha",
    area: "Contabilidade",
  }); // Dados do curso sendo editado

  // Função para buscar os cursos no backend
  const fetchCursos = async () => {
    try {
      const resposta = await fetch("http://localhost:5000/cursos");
      if (resposta.ok) {
        const dados = await resposta.json();
        setCursos(dados);
      } else {
        console.error("Erro ao buscar cursos");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Buscar cursos assim que o componente for montado
  useEffect(() => {
    fetchCursos();
  }, []);

  // Adicionar novo curso no backend e atualizar a lista
  const adicionarCurso = async () => {
    if (!novoCurso.trim()) return;

    const cursoData = {
      nome: novoCurso,
      nivel: 1,
      periodo: "Manha",
      area: "Contabilidade",
    }; // Valores padrão

    try {
      const resposta = await fetch("http://localhost:5000/cursos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(cursoData),
      });

      if (resposta.ok) {
        setNovoCurso("");
        fetchCursos(); // Atualiza a lista após adicionar
      } else {
        console.error("Erro ao adicionar curso");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Remover curso do backend e atualizar a lista
  const removerCurso = async (id) => {
    try {
      const resposta = await fetch(`http://localhost:5000/cursos/${id}`, {
        method: "DELETE",
      });

      if (resposta.ok) {
        fetchCursos(); // Atualiza a lista após remover
      } else {
        console.error("Erro ao remover curso");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Função para atualizar os dados do curso sendo editado
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Função para salvar as alterações de um curso
  const editarCurso = async () => {
    if (!formData.nome.trim()) return;

    try {
      const resposta = await fetch(
        `http://localhost:5000/cursos/${cursoEditando.id}`,
        {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(formData),
        }
      );

      if (resposta.ok) {
        setCursoEditando(null); // Limpa o curso em edição
        setFormData({
          nome: "",
          nivel: 1,
          periodo: "Manha",
          area: "Contabilidade",
        }); // Limpa os campos do formulário
        fetchCursos(); // Atualiza a lista após editar
      } else {
        console.error("Erro ao editar curso");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      {/* Formulário para adicionar novo curso */}
      <div className="mt-3">
        <h3>Cursos</h3>
        <div className="d-flex mb-3">
          <input
            type="text"
            className="form-control me-2"
            placeholder="Digite o nome do curso"
            value={novoCurso}
            onChange={(e) => setNovoCurso(e.target.value)}
          />
          <button className="btn btn-primary" onClick={adicionarCurso}>
            Adicionar
          </button>
        </div>
      </div>

      {/* Se estiver editando um curso, exibe o formulário de edição */}
      {cursoEditando && (
        <div className="mt-3">
          <h4>Editar Curso</h4>
          <div className="d-flex mb-3">
            <input
              type="text"
              className="form-control me-2"
              name="nome"
              placeholder="Nome do curso"
              value={formData.nome}
              onChange={handleChange}
            />
            <button className="btn btn-warning" onClick={editarCurso}>
              Salvar
            </button>
            <button
              className="btn btn-secondary"
              onClick={() => setCursoEditando(null)}
            >
              Cancelar
            </button>
          </div>
        </div>
      )}

      {/* Lista de cursos */}
      <ul className="list-group">
        {cursos.map((curso) => (
          <li
            key={curso.id}
            className="list-group-item d-flex justify-content-between align-items-center"
          >
            {curso.nome}
            <div>
              <button
                className="btn btn-outline-warning btn-sm"
                onClick={() => {
                  setCursoEditando(curso); // Inicia o processo de edição
                  setFormData({
                    nome: curso.nome,
                    nivel: curso.nivel,
                    periodo: curso.periodo,
                    area: curso.area,
                  });
                }}
              >
                ✏️ Editar
              </button>
              <button
                className="btn btn-outline-danger btn-sm"
                onClick={() => removerCurso(curso.id)}
              >
                🗑️
              </button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default AdmListCurso;
